    MyContract public contract;

    function setUp() public {
        contract = new MyContract();
    }

    function testFunction() public {
        // 测试逻辑
    }

    function testFuzz(uint256 x) public {
        // 模糊测试
    }
}
```

### Hardhat
```javascript
const { expect } = require("chai");

describe("MyContract", function () {
    it("Should work correctly", async function () {
        // 测试逻辑
    });
});
```

## 测试覆盖

### 目标覆盖率
- 单元测试: 90%+
- 集成测试: 覆盖所有主要流程
- 边界条件: 100% 覆盖

### 关键测试场景
1. 正常流程
2. 边界条件（0, 最大值, 最小值）
3. 错误条件（revert 情况）
4. 重入攻击
5. 访问控制
6. 整数溢出/下溢
7. Gas 限制

## 最佳实践

### 1. 使用 Fixtures
```solidity
function setUp() public {
    // 设置测试环境
}
```

### 2. 测试事件
```solidity
vm.expectEmit(true, true, false, true);
emit Transfer(from, to, amount);
contract.transfer(to, amount);
```

### 防护
- 使用 SafeERC20
- 检查返回值

## 4. 访问控制缺失

### 模式
```solidity
// ❌ 危险
function withdraw() public {
    // 任何人都可以调用
}
```

### 防护
- 使用 `onlyOwner` 或 `onlyRole` 修饰符
- 实现多签钱包控制
- 使用时间锁延迟关键操作

## 5. 时间戳依赖

### 模式
```solidity
// ❌ 危险：使用 block.timestamp 作为随机源
uint256 random = block.timestamp % 100;
```

### 防护
- 避免使用 block.timestamp 作为随机源
- 使用 Chainlink VRF 或其他可信随机源
- 使用 commit-reveal 方案

## 6. 前端运行 (Front-running)

### 模式
```solidity
// ❌ 危险：交易在 mempool 中可见
function buy(uint256 amount) public {
    uint256 price = calculatePrice(amount);
    // 攻击者可以抢先执行
}
```

# Gas 优化 / Gas Optimization

## 存储优化

### 1. 使用打包存储
```solidity
// ❌ 浪费 Gas
struct User {
    uint256 id;        // 32 bytes
    uint128 balance;   // 16 bytes
    uint128 timestamp; // 16 bytes
}

// ✅ 优化：打包到单个存储槽
struct User {
    uint128 balance;   // 16 bytes
    uint128 timestamp; // 16 bytes
    uint256 id;        // 32 bytes
}
```

### 2. 使用事件而非存储
对于不需要链上访问的数据，使用事件而非存储变量。

### 3. 缓存存储变量
```solidity
// ❌ 多次读取存储
function update() public {
    users[msg.sender].balance += 1;
    users[msg.sender].count += 1;
    users[msg.sender].lastUpdate = block.timestamp;
}

// ✅ 优化：缓存到内存
function update() public {
    User storage user = users[msg.sender];
    user.balance += 1;
    user.count += 1;
    user.lastUpdate = block.timestamp;
}
```

## 函数优化

### 1. 使用 external 而非 public
对于不需要内部调用的函数，使用 `external` 可以节省 Gas。

### 2. 批量操作
```solidity
// ❌ 多次调用
function transferMany(address[] memory to, uint256[] memory amounts) public {
    for (uint i = 0; i < to.length; i++) {
        transfer(to[i], amounts[i]);
    }
}

// ✅ 优化：批量处理
function transferMany(address[] memory to, uint256[] memory amounts) public {
    require(to.length == amounts.length, "Length mismatch");
    for (uint i = 0; i < to.length; i++) {
        _transfer(msg.sender, to[i], amounts[i]);
    }
}
```

### 3. 短路评估
```solidity
// ✅ 使用 && 和 || 的短路特性
if (condition1 && condition2) {
    // 如果 condition1 为 false，不会评估 condition2
}
```

## 循环优化

### 1. 缓存数组长度
```solidity
// ❌ 每次循环都读取长度
for (uint i = 0; i < array.length; i++) {
    // ...
}

// ✅ 优化：缓存长度
uint length = array.length;
for (uint i = 0; i < length; i++) {
    // ...
}
```

### 1. 存储布局兼容性
```solidity
// ❌ 错误：在现有变量之间插入新变量
contract V1 {
    uint256 public a;
    uint256 public b; // 新变量
    uint256 public c;
}

// ✅ 正确：在末尾添加新变量
contract V2 {
    uint256 public a;
    uint256 public c;
    uint256 public b; // 新变量在末尾
}
```

### 2. 初始化器保护
```solidity
contract MyContract {
    bool private initialized;

    function initialize() external {
        require(!initialized, "Already initialized");
        initialized = true;
        // 初始化逻辑
    }
}
```
